/* eslint-disable no-console */
import EventEmitter from 'eventemitter3';
import { Howler } from 'howler';

import { logAudioInfo } from './internal';
import { ExtendedAudioContextState } from './types';

export class SoundManagerContext extends EventEmitter<{
    contextStateChange: (state: ExtendedAudioContextState) => void;
}> {

    protected lastStateChange: AudioContextState | 'interrupted' = 'suspended';

    public static get supportsWebAudio(): boolean {
        return 'AudioContext' in window || 'webkitAudioContext' in window;
    }

    public static get contextState(): ExtendedAudioContextState {
        if (!this.supportsWebAudio) {
            return 'running';
        }

        if (Howler && Howler.ctx) {
            return Howler.ctx.state as ExtendedAudioContextState;
        }

        return 'suspended';
    }

    protected stateShouldBe: 'resume' | 'suspend' = 'resume';
    protected howlerContextIntervalId: number | undefined;

    public constructor() {
        super();
        this.on('contextStateChange', (contextState) => {
            logAudioInfo('context state changed: ', contextState);
            if (contextState === 'interrupted') {
                this.clearResumeTimeout();
            }
            this.lastStateChange = contextState;
        });
        this.waitForHowlerContext();
    }

    private async onVisibilityChange(): Promise<void> {
        if (!Howler.ctx) {
            return;
        }
        logAudioInfo('visibility changed, current state: ', document.visibilityState);
        if (document.hidden) {
            this.suspend();
        } else {
            this.attemptResume(250);
        }
    }

    protected waitForHowlerContext(): void {
        this.howlerContextIntervalId = window.setInterval(() => {
            this.setupHowlerContextListeners();
        }, 100);
    }

    public async resume(): Promise<void> {
        if (!Howler.ctx) {
            return;
        }
        this.clearResumeTimeout();
        logAudioInfo('attempting to resume context');
        return Howler.ctx.resume().then(() => {
            logAudioInfo('successfully resumed audio context');
        }).catch((err) => {
            logAudioInfo('Error while resuming audio context, will attempt again in 250ms', err);
            this.attemptResume(250);
        });
    }

    public async suspend(): Promise<void> {
        if (!Howler.ctx) {
            return;
        }
        this.clearResumeTimeout();
        return Howler.ctx.suspend().then(() => {
            logAudioInfo('successfully suspended audio context');
        }).catch((err) => {
            logAudioInfo('Error while suspending audio context, no further attempts', err);
        });
    }

    protected hackHowlerContextResumes(): void {
        const originalResume = Howler.ctx.resume.bind(Howler.ctx);
        const originalSuspend = Howler.ctx.suspend.bind(Howler.ctx);
        Howler.ctx.resume = () => {
            logAudioInfo('howler context resume called');
            return originalResume().catch((err) => {
                logAudioInfo('error on resume: ', err);
                throw err;
            });
        };
        Howler.ctx.suspend = () => {
            logAudioInfo('howler context suspend called');
            return originalSuspend().catch((err) => {
                logAudioInfo('error on suspend: ', err);
                throw err;
            });
        };
    }

    protected setupHowlerContextListeners(): void {
        if (Howler && Howler.ctx) {
            const hasEventHandlers = !!Howler.ctx.addEventListener;
            if (!hasEventHandlers) {
                this.setupHowlerStateChangeLegacyListener();
                return;
            }
            window.clearInterval(this.howlerContextIntervalId);
            document.addEventListener('visibilitychange', this.onVisibilityChange.bind(this));
            this.setupHowlerStateChangeListener();
            this.hackHowlerContextResumes();
        }
    }

    protected setupHowlerStateChangeLegacyListener(): void {
        logAudioInfo('setting up legacy change listener');
        this.emit('contextStateChange', SoundManagerContext.contextState);
        this.howlerContextIntervalId = window.setInterval(() => {
            const wasLastStateInterrupted = this.lastStateChange === 'interrupted' && SoundManagerContext.contextState !== 'interrupted';
            if (this.lastStateChange !== SoundManagerContext.contextState) {
                this.emit('contextStateChange', SoundManagerContext.contextState);
            }
            if (wasLastStateInterrupted) {
                this.attemptResume(250);
            }
        }, 100);
    }

    protected setupHowlerStateChangeListener(): void {
        logAudioInfo('setting up standard change listener');
        this.emit('contextStateChange', SoundManagerContext.contextState);
        Howler.ctx.addEventListener('statechange', () => {
            const wasLastStateInterrupted = this.lastStateChange === 'interrupted' && SoundManagerContext.contextState !== 'interrupted';
            this.emit('contextStateChange', SoundManagerContext.contextState);
            if (wasLastStateInterrupted) {
                this.attemptResume(250);
            }
        });
    }

    protected attemptResumeId: number | undefined;

    protected clearResumeTimeout(): void {
        if (this.attemptResumeId) {
            window.clearTimeout(this.attemptResumeId);
            this.attemptResumeId = undefined;
        }
    }

    protected attemptResume(delayInMS: number): void {
        logAudioInfo(`attempting resume with delay: ${delayInMS}`);
        this.attemptResumeId = window.setTimeout(() => {
            this.clearResumeTimeout();
            logAudioInfo(`attempting resume [${this.stateShouldBe}]`);
            this.resume();
        }, delayInMS);
    }
}